function applyMentorTheme(v){document.documentElement.dataset.theme=v;localStorage.setItem('mentor-theme',v);const i=$('#mentorTheme i');if(i)i.setAttribute('class',v==='dark'?'fa-solid fa-sun':'fa-solid fa-moon')}
